void LB_Normal_PowerMode(void)
{
    m_current_isd = Addr_SharedMem->connected_ISD_num;

    /* If any ISD has connected, the number is definitely not zero */
    if (m_current_isd != 0)
    {
        Normal_PowerMode_isdConnected();
    }
    else
