     * 각각 어떤 주파수 그룹으로 할당할 것인지 정보가 구성되어 있다. */

    int _IOMEM* p_FS_num_of_freqBand = (int _IOMEM*) ADDR_NUM_OF_FREQ_BAND_IN_FS_MEM;
    int _IOMEM* p_FS_indexPassBin    = (int _IOMEM*) ADDR_FFT_PASS_BIN_IN_FS_MEM;

