bool tdc_touch_iqs323_is_ati_done(void)
{
    tdc_touch_iqs323_status_t st;

    if (!tdc_touch_iqs323_read_status(&st))
    {
        return false; /* read 실패/글리치 -> 미완료로 재시도 */
    }
    return (st.ati_active == false);
}

