bool check_FPGA_FIFO_empty(bool *isEmpty)
{
    int        readValue;
    int        temp;
    static int error_cnt = 0;

#ifdef CM3_I2C_controls_FPAG
    if (read_ISD_by_CM3_I2C(i2cAddr_FPGA_systemResgister_2nd, &readValue, 1))
#else
