            {
                remoteDataPacket.remocon_ReadWriteMapData_Flash.slot_index = tempValue;
                remoteDataPacket.remocon_ReadWriteMapData_Flash.map_index  = 0;
                remoteDataPacket.command                                   = en__remoteControl_read_SlotData_ISD_N_USER;
