int get_manifest_files(char *src, char *dst, int len)
{
    int i;
    i = 0;
    if (src == NULL || dst == NULL)
    {
        return -1;
    }
    if (len <= 0)
    {
        return 0;
    }

    memset(dst, '\0', len);
    while (i < len)
    {
        if (src[i] == '\0' || src[i] == '\n')
        {
            dst[i] = '\0';
            break;
        }
        else
        {
            dst[i] = src[i];
        }
        i++;
    }
    return i;
}

