BOOT-033.body:
int bootloader_decrypt_data(struct AES_ctx *aes_context, uint32_t *data, size_t len)
{
    uint32_t  i;
    uint32_t *p;

    /* len is not an integer number of AES blocks. */
    if ((len & 0x03) != 0)
    {
        return -1;
    }

    for (i = 0; i < len; i++)
    {
        data[i] = htonl(data[i]);
    }

    p = data;
    for (i = 0; i < (len >> 2); i++)
    {
        AES_ECB_decrypt(aes_context, (unsigned char *) p);
        p += 4;
    }

    for (i = 0; i < len; i++)
    {
        data[i] = htonl(data[i]);
    }
    return 0;
}

